export function createWcPaperHolderWoodTexture(isEdge = false) {
  const source = isEdge ? edge : face, width = 128, height = isEdge ? 16 : 128;
  const mean = isEdge ? [70, 43, 31] : [218, 174, 140];
  const target = isEdge ? [111, 76, 55] : [168, 125, 96];
  const contrast = isEdge ? .88 : .82;
  const rgba = new Uint8Array(width * height * 4);
  for (let i = 0; i < width * height; i++) {
    for (let c = 0; c < 3; c++) rgba[i * 4 + c] = Math.max(0, Math.min(255, Math.round(target[c] + (source[i * 3 + c] - mean[c]) * contrast)));
    rgba[i * 4 + 3] = 255;
  }
  const texture = new DataTexture(rgba, width, height, RGBAFormat, UnsignedByteType);
  texture.name = "photo:aliexpress-1005013624521211:" + (isEdge ? "edge" : "face");
  texture.colorSpace = SRGBColorSpace;
  texture.wrapS = texture.wrapT = ClampToEdgeWrapping;
  texture.magFilter = LinearFilter; texture.minFilter = LinearMipmapLinearFilter;
  texture.generateMipmaps = true; texture.anisotropy = 8; texture.needsUpdate = true;
  return texture;
}
